  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <circle cx="12" cy="12" r="10" />
    <path d="M12 16v-4M12 8h.01" />
  </svg>
);
export function Example() {
  const args: Pick<
    ComponentProps<typeof Callout>,
    'tone' | 'icon' | 'title' | 'children'
  > = {
    tone: 'info',
    icon: iconInfo,
    title: 'Your collection is being prepared',
